/* prog18_caesar_cipher.c
 * Reimplementation of the original binary's observable behaviour.
 * It reads a shift amount and a message from the command line,
 * applies a Caesar cipher (shift modulo 26) to the message,
 * prints the result followed by a newline, or prints "USAGE"
 * when the arguments are invalid.
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

static void usage(void) {
    puts("USAGE");
}

/* Reduce an integer to the range 0‑25 (mod 26) */
static int norm_shift(long v) {
    int s = (int)(v % 26);
    if (s < 0) s += 26;
    return s;
}

/* Apply Caesar shift to a single character */
static char shift_char(char c, int shift) {
    if ('A' <= c && c <= 'Z')
        return (char)('A' + (c - 'A' + shift) % 26);
    if ('a' <= c && c <= 'z')
        return (char)('a' + (c - 'a' + shift) % 26);
    return c;
}

int main(int argc, char **argv) {
    if (argc != 3) {
        usage();
        return 0;
    }

    /* ----- parse shift ----- */
    char *endptr;
    long raw = strtol(argv[1], &endptr, 10);
    if (*endptr != '\0') {          /* non‑numeric characters */
        usage();
        return 0;
    }
    int shift = norm_shift(raw);

    /* ----- validate message length ----- */
    const char *msg = argv[2];
    size_t len = strlen(msg);
    if (len > 1024) {
        usage();
        return 0;
    }

    /* ----- encode and output ----- */
    for (size_t i = 0; i < len; ++i) {
        putchar(shift_char(msg[i], shift));
    }
    putchar('\n');

    return 0;
}
